from .api import (create_api_client, RapManagerApi,
                  DEFAULT_USER, DEFAULT_PASSWORD, DEFAULT_PORT)
from taf.internal.aliasing import aliasing_scope
from taf.internal.robot_typecasts import time_to_seconds


class rap_manager(object):

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    lookup_handler, client_store = aliasing_scope(name=__name__, lookup_arg='client',
                                                  lookup_type=RapManagerApi)

    def create_session(self, url, user=DEFAULT_USER,
                       password=DEFAULT_PASSWORD, port=DEFAULT_PORT,
                       timeout=10, alias=None):
        """Setup a new client.

        :param str url: URL of the host without a port designator, e.g.:
            "https://1.2.3.4/".
        :param str user: (Optional) username, defaults to "Nemuadmin".
        :param str password: (Optional) password, defaults to "nemuuser".
        :param int port: (Optional) server port, defaults to 8666.
        :param timeout: (Optional) timeout for the authentication process. Can
            be given by either int (number of seconds) or a string with Robot
            Framework time notation.
        :param alias: (optional) alias that the new session object will be
            identified by. If not specified, string "default" is used.
        :raises ConnectionError: if server responds with anything other than
            HTTP 200 during authentication.
        :raises requests.Timeout: if timeout occured.
        :return: Initialized API object.
        :rtype: RapManagerApi
        """
        timeout = time_to_seconds(timeout)
        client = create_api_client(url, user, password, port, timeout)
        self.client_store.add(client, alias)
        return client

    @lookup_handler.implicit_lookup
    def enable_ethernet_port_security(self, client=None):
        """Set "ethernet port security" feature state to "enabled".

        :param client: Alias of the client given (see `alias` in
            :py:func:`create_session()`), or the client object itself.
        """
        client.enable_ethernet_port_security()

    @lookup_handler.implicit_lookup
    def disable_ethernet_port_security(self, client=None):
        """Set "ethernet port security" feature state to "disabled".

        :param client: Alias of the client given (see `alias` in
            :py:func:`create_session()`), or the client object itself.
        """
        client.disable_ethernet_port_security()

    @lookup_handler.implicit_lookup
    def get_ethernet_port_security_state(self, client=None):
        """Return current state of "ethernet port security" feature.

        :param client: Alias of the client given (see `alias` in
            :py:func:`create_session()`), or the client object itself.
        :return: True if enabled, False otherwise.
        :rtype: bool
        """
        return client.ethernet_port_security_enabled

