    @lookup_handler.implicit_lookup
    def get_vnf_connection_state(self, client=None):
        """Get the state of VNF connection from RAP Manager.

        :param client: Alias of the client given (see `alias` in
            :py:func:`create_session()`), or the client object itself.
        :return: True if the state is "connected", False otherwise.
        :rtype: bool
        """
        return client.connected_to_vnf
